mapper.select:

        /* 공통팀 유민상 isry.sample.mapper.AimnsTrainessCostMapper.selectTrainessCostList 공통팀 유민상*/

        SELECT *
		FROM PIVOT_TEST 
		PIVOT (
		    MAX(COST) AS COST, MAX(ATTENDANCE_RATE) AS RATE
		    FOR YEAR_MONTH IN 

                '${item.DATE}' AS ${item.ALIAS}

		)
		WHERE 1=1
        ORDER BY EX_NAME
